// Code snippet to check if a target domain is a subdomain of a given domain
function isSubdomain(targetDomain, domain) {
  const domainParts = domain.split('.');
  const targetParts = targetDomain.split('.');

  // Normalize parts by removing empty strings
  const normalizedDomainParts = domainParts.filter(part => part !== '');
  const normalizedTargetParts = targetParts.filter(part => part !== '');

  // Check if target is a subdomain
  if (normalizedTargetParts.length > normalizedDomainParts.length) {
    const subdomainParts = normalizedTargetParts.slice(0, normalizedDomainParts.length);
    return subdomainParts.join('.') === domain;
  }
  return false;
}

